// Vendored benchmark fixture "dependency" (scripts/bench/fixtures/node_modules/bench-dep).
// Lives under a committed node_modules/ dir so capwall's attribution walks a real
// `node_modules/bench-dep/…` path and resolves the owning package name, instead of
// short-circuiting to the `<app>` sentinel — see scripts/bench/README.md for why that
// matters for the measurement. Mirrors packages/core/test/fixtures/node_modules/fixture-dep.
//
// EVERY capability surface it touches is captured at require() time, into a module-level
// binding. That is what makes the two-arm measurement honest: the instance `require`d BEFORE
// capwall installs holds the real builtins / the real `process.env` / the real `fetch`, the
// instance `require`d fresh AFTER install holds capwall's shims, and bench.mjs runs the two
// side by side in one process. A LAZY `require("net")` inside a function would defeat that —
// `Module._load` is patched process-wide, so the "baseline" instance would get the shim back.
// If you add a surface here, capture it at module scope.
//
// This package is GRANTED what it needs by the benchmark's policy. The deny-path scenarios are
// driven from the sibling `bench-dep-denied`, which is granted nothing.
"use strict";
const fs = require("fs");
const net = require("net");
const http = require("http");
const child_process = require("child_process");
const path = require("path");

// `process.env` is replaced by capwall's read-gating Proxy in `install()`; `globalThis.fetch`
// is replaced by the global-egress guard. Both are captured, not re-read, for the reason above.
const env = process.env;
const fetchFn = globalThis.fetch;

const DATA = path.join(__dirname, "data.txt");
exports.dir = __dirname;
exports.dataPath = DATA;

/** Plain sync read — the hot-path operation the fs scenario times. */
exports.readSync = () => fs.readFileSync(DATA, "utf8");

/**
 * The same read, reached through `depth` further frames OF THIS PACKAGE.
 *
 * Attribution captures up to `maxFrames` (default 25) CallSites on every mediated call, and V8
 * charges for each frame it materializes — so the cost is a function of how deep the stack is
 * when the call happens, not a constant. A benchmark that only ever calls from three frames
 * down measures the cheapest stack a real program can have. See scripts/bench/README.md
 * § "Stack depth is a parameter, not a constant".
 */
exports.readSyncAtDepth = function readSyncAtDepth(depth) {
  if (depth <= 0) return fs.readFileSync(DATA, "utf8");
  return exports.readSyncAtDepth(depth - 1);
};

/** `fs.globSync` (Node >= 22) — the enumeration family, one decision per pattern. */
exports.globSync = (pattern, options) => fs.globSync(pattern, options);
exports.hasGlobSync = typeof fs.globSync === "function";

/**
 * Invoke `attributeCallerFn` from a frame that lives under node_modules/bench-dep, so the
 * stack-walk resolves a real package name (not `<app>`). Used to time attribution alone,
 * decoupled from a full shimmed fs call.
 */
exports.callAttribute = (attributeCallerFn, opts) => attributeCallerFn(opts);

/** `attributeCallerFn` reached through `depth` further frames of this package. */
exports.attributeAtDepth = function attributeAtDepth(attributeCallerFn, opts, depth) {
  if (depth <= 0) return attributeCallerFn(opts);
  return exports.attributeAtDepth(attributeCallerFn, opts, depth - 1);
};

/**
 * A `net.connect` with a MULTI-PROPERTY options bag — the shape that exercises the shim's
 * accessor-flattening clone (#26/#56): every own field of the bag is read exactly once and
 * written to an inert copy before Node ever sees it, so the cost scales with how many own
 * properties the caller passes. A one-key bag would under-measure it.
 *
 * The socket is destroyed immediately; both arms (real `net` and capwall's shim) do the same
 * OS work, so the paired delta is capwall's own cost.
 */
exports.connect = (options) => {
  const s = net.connect(options);
  s.on("error", () => {});
  s.destroy();
  return s;
};

/**
 * Attempt a call the benchmark's policy never grants. In enforce mode the shim throws
 * `CapabilityError` synchronously, before any socket opens — a deterministic way to time the
 * attribute→evaluate→throw path with no real I/O. (Granted to nobody: driven from
 * `bench-dep-denied`, which is why the same helper lives there too.)
 */
exports.connectDenied = (host, port) => {
  try {
    const s = net.connect({ host, port });
    s.on("error", () => {});
    s.destroy();
    return { threw: false };
  } catch (err) {
    return { threw: true, name: err && err.name };
  }
};

/**
 * `child_process.spawnSync` — the surface that carries the per-key env authorization (#89):
 * capwall pins every own field of the options bag, then builds an explicit `options.env` by
 * snapshotting the UN-proxied environment key by key, so Node's own
 * `options.env || { ...process.env }` never enumerates the read gate. Both of those scale with
 * the size of the environment, which is why the benchmark measures a real spawn rather than a
 * denied one.
 */
exports.spawnSync = (cmd, args, options) => child_process.spawnSync(cmd, args, options);

/** One `process.env` read — through capwall's Proxy on the shimmed instance. */
exports.envRead = (key) => env[key];

/**
 * `{ ...process.env }` — the shape `dotenv`, config loaders and Node's own spawn use, and the
 * one that costs. Object spread runs `[[OwnPropertyKeys]]`, then `[[GetOwnProperty]]` AND
 * `[[Get]]` per key, and capwall's env Proxy attributes the caller on both of the latter two.
 * So the cost is not one attribution, it is ~2 per environment variable.
 */
exports.envSpread = () => ({ ...env });
exports.envKeyCount = Object.keys(env).length;

/**
 * One property read off `http.globalAgent`, which capwall hands out as a per-property Proxy
 * (#65) so `globalAgent.createConnection(...)` is gated like every other egress entry point.
 * Every OTHER property read pays that Proxy's `get` trap too — this measures that tax.
 */
exports.agentProperty = () => http.globalAgent.maxSockets;

/** One `fetch` — the GLOBAL egress guard (#80), not a module surface. Returns the promise. */
exports.fetchCall = (url) => fetchFn(url);
exports.hasFetch = typeof fetchFn === "function";
